"use strict";(globalThis.webpackChunkmomento_docs||=[]).push([[1171],{22942(e,t,a){a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>i,default:()=>h,frontMatter:()=>s,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"self-hosted/valkey-operator/why-this-operator","title":"Why this operator","description":"The top factual benefits of the Momento Valkey Operator, grounded in shipped behavior.","source":"@site/docs/self-hosted/valkey-operator/why-this-operator.md","sourceDirName":"self-hosted/valkey-operator","slug":"/self-hosted/valkey-operator/why-this-operator","permalink":"/ja/self-hosted/valkey-operator/why-this-operator","draft":false,"unlisted":false,"editUrl":"https://github.com/momentohq/public-dev-docs/tree/main/docs/self-hosted/valkey-operator/why-this-operator.md","tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"title":"Why this operator","description":"The top factual benefits of the Momento Valkey Operator, grounded in shipped behavior.","sidebar_position":2},"sidebar":"siteSidebar","previous":{"title":"Momento Valkey Operator","permalink":"/ja/self-hosted/valkey-operator/"},"next":{"title":"Getting started","permalink":"/ja/self-hosted/valkey-operator/getting-started/"}}');var r=a(74848),n=a(28453);const s={title:"Why this operator",description:"The top factual benefits of the Momento Valkey Operator, grounded in shipped behavior.",sidebar_position:2},i="Why this operator",l={},c=[{value:"Governance is built into the resource model, not bolted on",id:"governance-is-built-into-the-resource-model-not-bolted-on",level:2},{value:"Direct pod management for topology-aware operations",id:"direct-pod-management-for-topology-aware-operations",level:2},{value:"Explicit, deliberate engine versioning",id:"explicit-deliberate-engine-versioning",level:2},{value:"No cap on clusters per namespace",id:"no-cap-on-clusters-per-namespace",level:2},{value:"TLS-only mode and structured ACLs",id:"tls-only-mode-and-structured-acls",level:2},{value:"Zone-aware placement with hard per-shard guarantees",id:"zone-aware-placement-with-hard-per-shard-guarantees",level:2},{value:"Predictable, observable reconciliation",id:"predictable-observable-reconciliation",level:2},{value:"An honest operations story",id:"an-honest-operations-story",level:2}];function d(e){const t={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.header,{children:(0,r.jsx)(t.h1,{id:"why-this-operator",children:"Why this operator"})}),"\n",(0,r.jsx)(t.p,{children:"This page states the Momento Valkey Operator's top benefits factually, each grounded in behavior documented elsewhere in these docs. It does not compare against named products; where useful, it anchors a claim against typical expectations for operators of stateful systems on Kubernetes."}),"\n",(0,r.jsx)(t.h2,{id:"governance-is-built-into-the-resource-model-not-bolted-on",children:"Governance is built into the resource model, not bolted on"}),"\n",(0,r.jsxs)(t.p,{children:["Many operators for stateful systems leave governance to whatever the platform team can construct externally: admission webhooks, a separate policy engine, or process discipline. This operator's governance is the resource model itself: an allowlist of permitted images, a curated menu of configuration profiles, and reusable ACL role definitions all live as cluster-scoped custom resources, readable by every namespace but writable only by the platform team. A product team's ",(0,r.jsx)(t.code,{children:"ValkeyCluster"})," can only ever reference what the platform team has already published: there is no field where an unapproved image or setting could go. No admission webhook is required for this to hold. See ",(0,r.jsx)(t.a,{href:"/ja/self-hosted/valkey-operator/concepts/resource-model",children:"Resource model"}),"."]}),"\n",(0,r.jsx)(t.h2,{id:"direct-pod-management-for-topology-aware-operations",children:"Direct pod management for topology-aware operations"}),"\n",(0,r.jsxs)(t.p,{children:["Generic Kubernetes workload controllers reconcile a pod count against a template; they have no concept of shard membership, primary/replica role, or replication sync state. This operator manages pods directly so it can express operations that require that awareness: replacing a node only after its successor has joined and synced, and performing exactly one coordinated failover per shard during a rolling change, never more, never as a side effect of an unrelated pod restart. See ",(0,r.jsx)(t.a,{href:"/ja/self-hosted/valkey-operator/concepts/pod-management",children:"Pod management"}),"."]}),"\n",(0,r.jsx)(t.h2,{id:"explicit-deliberate-engine-versioning",children:"Explicit, deliberate engine versioning"}),"\n",(0,r.jsxs)(t.p,{children:["Every image a cluster can run comes from the platform team's allowlist, and nothing in the operator initiates an engine upgrade on its own. A cluster moves to a different image only when what its config resolves to changes: the platform team repoints a ",(0,r.jsx)(t.code,{children:"ValkeyConfig"}),"'s ",(0,r.jsx)(t.code,{children:"imageRef"})," or edits a registered ",(0,r.jsx)(t.code,{children:"ValkeyImage"}),", or a product team switches its cluster to a different config from the approved menu. Every one of those is an explicit, auditable Kubernetes resource change made by a person; none happens automatically. See ",(0,r.jsx)(t.a,{href:"/ja/self-hosted/valkey-operator/platform-guide/valkey-upgrades",children:"Managing Valkey upgrades"}),"."]}),"\n",(0,r.jsx)(t.h2,{id:"no-cap-on-clusters-per-namespace",children:"No cap on clusters per namespace"}),"\n",(0,r.jsxs)(t.p,{children:["A namespace can hold any number of ",(0,r.jsx)(t.code,{children:"ValkeyCluster"})," resources. Product teams are free to organize clusters (one per application, one per environment, or any other scheme) without the operator itself imposing a one-cluster-per-namespace ceiling, which is a real constraint some operators for stateful systems apply. See ",(0,r.jsx)(t.a,{href:"/ja/self-hosted/valkey-operator/team-guide/provisioning",children:"Provisioning a cluster"}),"."]}),"\n",(0,r.jsx)(t.h2,{id:"tls-only-mode-and-structured-acls",children:"TLS-only mode and structured ACLs"}),"\n",(0,r.jsxs)(t.p,{children:["A Valkey cluster can run TLS-only, encrypting client traffic, replication, and the cluster bus, with the plaintext port closed entirely. Access control is expressed structurally (reusable permission roles, key-pattern scoping, and password-hash rotation) rather than as hand-assembled ACL strings a platform team has to get right by hand on every cluster. See ",(0,r.jsx)(t.a,{href:"/ja/self-hosted/valkey-operator/security/",children:"Security"}),"."]}),"\n",(0,r.jsx)(t.h2,{id:"zone-aware-placement-with-hard-per-shard-guarantees",children:"Zone-aware placement with hard per-shard guarantees"}),"\n",(0,r.jsxs)(t.p,{children:["With required zone spread, every shard's members are guaranteed to land across distinct availability zones (a hard constraint enforced by Kubernetes scheduling, not a best-effort preference), so a single zone failure cannot, by construction, take out both a shard's primary and all its replicas. See ",(0,r.jsx)(t.a,{href:"/ja/self-hosted/valkey-operator/operations/zone-aware-placement",children:"Zone-aware placement"}),"."]}),"\n",(0,r.jsx)(t.h2,{id:"predictable-observable-reconciliation",children:"Predictable, observable reconciliation"}),"\n",(0,r.jsxs)(t.p,{children:["Where many controllers reconcile by re-evaluating and applying a full desired state, this operator takes at most one corrective action per reconciliation pass, then requeues. A cluster's formation is snapshotted into ",(0,r.jsx)(t.code,{children:"status.targetSpec"}),", and every node's join/leave progress is visible through its ",(0,r.jsx)(t.code,{children:"ValkeyNode"})," resource, so a platform team can watch a change happen step by step rather than treating the operator as a black box. This bounds the blast radius of any single mistake or fault to one small step. See ",(0,r.jsx)(t.a,{href:"/ja/self-hosted/valkey-operator/concepts/reconciliation",children:"Reconciliation"}),"."]}),"\n",(0,r.jsx)(t.h2,{id:"an-honest-operations-story",children:"An honest operations story"}),"\n",(0,r.jsxs)(t.p,{children:["Operators for stateful systems on Kubernetes often stay quiet about what happens to data when things go wrong, leaving teams to discover the answer during an incident. This operator's documentation states the storage model plainly: Valkey clusters are in-memory, and durability comes from replication, failover, and placement, not from disks. Exactly which failure events lose data, and which don't, is written down rather than implied. For a team evaluating a system that will hold production data, that itself is a benefit: what you read here is what you will observe in production, with no gap between the two. See ",(0,r.jsx)(t.a,{href:"/ja/self-hosted/valkey-operator/concepts/data-durability",children:"Data durability"}),"."]})]})}function h(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},28453(e,t,a){a.d(t,{R:()=>s,x:()=>i});var o=a(96540);const r={},n=o.createContext(r);function s(e){const t=o.useContext(n);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),o.createElement(n.Provider,{value:t},e.children)}}}]);